def transform(grid):
    h, w = len(grid), len(grid[0])
    div = next(c for c in range(w)
               if all(grid[r][c] == grid[0][c] for r in range(h))
               and 0 < c < w - 1)
    n = min(div, w - div - 1)
    left = [grid[r][div-n:div] for r in range(h)]
    right = [grid[r][div+1:div+1+n] for r in range(h)]

    def most_common(part):
        counts = {}
        for row in part:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    left_bg, right_bg = most_common(left), most_common(right)
    return [
        [3 if left[r][c] != left_bg and right[r][c] != right_bg else 4
         for c in range(n)]
        for r in range(h)
    ]
